package onl.tesseract.tesseractlib.util.menu;

import org.bukkit.inventory.ItemStack;

public enum InventoryHeadIcons {
    LEFT_ARROW("Gauche", "", ""),
    RIGHT_ARROW("Droite", "", ""),
    ;
    private final ItemStack item;

    InventoryHeadIcons(final String name, final String data, final String signature)
    {
        item = InventoryMenu.getCustomHead(name, data, signature);
    }

    public ItemStack getItem() {
        return item;
    }
}
